<?php
require __DIR__ . '/db.php';
session_name($config['session_name'] ?? 'portal_guru_admin');
session_start();

function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function csrf(){if(empty($_SESSION['csrf']))$_SESSION['csrf']=bin2hex(random_bytes(24));return $_SESSION['csrf'];}
function checkCsrf(){if(!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??''))exit('CSRF tidak valid');}
function redirectAdmin($q=''){header('Location: admin.php'.$q);exit;}
function setting(PDO $pdo,$k,$d=''){static $cache=null;if($cache===null){$cache=[];foreach($pdo->query('SELECT setting_key,setting_value FROM settings') as $r)$cache[$r['setting_key']]=$r['setting_value'];}return $cache[$k]??$d;}
function setSetting(PDO $pdo,$k,$v){$st=$pdo->prepare('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value)');$st->execute([$k,$v]);}
function slugify($s){$s=strtolower(trim($s));$s=preg_replace('/[^a-z0-9]+/','-',$s);return trim($s,'-')?:'materi-'.time();}

$error='';
if(isset($_GET['logout'])){session_destroy();redirectAdmin();}
if(empty($_SESSION['admin_id'])){
  if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='login'){
    $st=$pdo->prepare('SELECT * FROM users WHERE username=? LIMIT 1');$st->execute([trim($_POST['username']??'')]);$u=$st->fetch();
    if($u && password_verify($_POST['password']??'',$u['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$u['id'];$_SESSION['admin_user']=$u['username'];csrf();redirectAdmin();}
    $error='Username atau password salah.';
  }
  ?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Login Admin</title><style>body{font-family:system-ui;margin:0;background:#f5f7fb;color:#0f172a}.login{max-width:420px;margin:9vh auto;background:#fff;border:1px solid #e2e8f0;border-radius:18px;padding:28px;box-shadow:0 18px 50px rgba(15,23,42,.08)}input{width:100%;box-sizing:border-box;padding:12px;margin:6px 0 14px;border:1px solid #cbd5e1;border-radius:10px}button{width:100%;padding:12px;border:0;border-radius:10px;background:#2563eb;color:white;font-weight:700}.err{padding:10px;background:#fef2f2;color:#b91c1c;border-radius:9px}</style></head><body><div class="login"><h1>Portal Guru Admin</h1><p>Masuk untuk mengelola isi landing page.</p><?php if($error):?><p class="err"><?=h($error)?></p><?php endif;?><form method="post"><input type="hidden" name="action" value="login"><label>Username</label><input name="username" required autofocus><label>Password</label><input name="password" type="password" required><button>Masuk</button></form></div></body></html><?php exit;
}

if($_SERVER['REQUEST_METHOD']==='POST'){
  checkCsrf();$action=$_POST['action']??'';
  if($action==='save_profile'){
    foreach(['name','title','school','location','bio','email','whatsapp','photo','logo'] as $k)setSetting($pdo,'profile_'.$k,trim($_POST[$k]??''));
    redirectAdmin('?saved=profile#profil');
  }
  if($action==='save_links'){
    foreach(['sibela','classroom','drive','github','school'] as $k)setSetting($pdo,'link_'.$k,trim($_POST[$k]??''));
    redirectAdmin('?saved=links#tautan');
  }
  if($action==='save_material'){
    $id=(int)($_POST['id']??0);$slug=trim($_POST['slug']??'')?:slugify(($_POST['class_name']??'').' '.($_POST['tp']??'').' '.($_POST['title']??''));
    $data=[$slug,trim($_POST['class_name']??''),trim($_POST['mapel']??''),trim($_POST['tp']??''),trim($_POST['title']??''),trim($_POST['summary']??''),trim($_POST['content']??''),trim($_POST['tags']??''),trim($_POST['resource_url']??''),(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0];
    if($id){$st=$pdo->prepare('UPDATE materials SET slug=?,class_name=?,mapel=?,tp=?,title=?,summary=?,content=?,tags=?,resource_url=?,sort_order=?,is_active=? WHERE id=?');$st->execute([...$data,$id]);}
    else{$st=$pdo->prepare('INSERT INTO materials(slug,class_name,mapel,tp,title,summary,content,tags,resource_url,sort_order,is_active) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$st->execute($data);}
    redirectAdmin('?saved=material#materi');
  }
  if($action==='delete_material'){$st=$pdo->prepare('DELETE FROM materials WHERE id=?');$st->execute([(int)$_POST['id']]);redirectAdmin('#materi');}
  if($action==='save_module'){
    $id=(int)($_POST['id']??0);$data=[trim($_POST['title']??''),trim($_POST['class_name']??''),trim($_POST['type']??''),trim($_POST['description']??''),trim($_POST['file_url']??''),(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0];
    if($id){$st=$pdo->prepare('UPDATE modules SET title=?,class_name=?,type=?,description=?,file_url=?,sort_order=?,is_active=? WHERE id=?');$st->execute([...$data,$id]);}
    else{$st=$pdo->prepare('INSERT INTO modules(title,class_name,type,description,file_url,sort_order,is_active) VALUES(?,?,?,?,?,?,?)');$st->execute($data);}
    redirectAdmin('?saved=module#modul');
  }
  if($action==='delete_module'){$st=$pdo->prepare('DELETE FROM modules WHERE id=?');$st->execute([(int)$_POST['id']]);redirectAdmin('#modul');}
  if($action==='save_portfolio'){
    $id=(int)($_POST['id']??0);$data=[trim($_POST['title']??''),trim($_POST['student']??''),trim($_POST['class_name']??''),trim($_POST['description']??''),trim($_POST['image_url']??''),trim($_POST['demo_url']??''),trim($_POST['repo_url']??''),(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0];
    if($id){$st=$pdo->prepare('UPDATE portfolio SET title=?,student=?,class_name=?,description=?,image_url=?,demo_url=?,repo_url=?,sort_order=?,is_active=? WHERE id=?');$st->execute([...$data,$id]);}
    else{$st=$pdo->prepare('INSERT INTO portfolio(title,student,class_name,description,image_url,demo_url,repo_url,sort_order,is_active) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute($data);}
    redirectAdmin('?saved=portfolio#portofolio');
  }
  if($action==='delete_portfolio'){$st=$pdo->prepare('DELETE FROM portfolio WHERE id=?');$st->execute([(int)$_POST['id']]);redirectAdmin('#portofolio');}
}

$editMat=!empty($_GET['edit_material'])?$pdo->query('SELECT * FROM materials WHERE id='.(int)$_GET['edit_material'])->fetch():null;
$editMod=!empty($_GET['edit_module'])?$pdo->query('SELECT * FROM modules WHERE id='.(int)$_GET['edit_module'])->fetch():null;
$editPor=!empty($_GET['edit_portfolio'])?$pdo->query('SELECT * FROM portfolio WHERE id='.(int)$_GET['edit_portfolio'])->fetch():null;
$materials=$pdo->query('SELECT * FROM materials ORDER BY sort_order,id')->fetchAll();
$modules=$pdo->query('SELECT * FROM modules ORDER BY sort_order,id')->fetchAll();
$portfolio=$pdo->query('SELECT * FROM portfolio ORDER BY sort_order,id')->fetchAll();
?>
